sys_script_email.script:
(function (current, template) {
  // Base URL of this instance, ends with '/'
  var base = gs.getProperty('glide.servlet.uri'); 

  // Table & sys_id from the triggering record
  var table = current.getTableName();
  var id = current.getUniqueValue();

  // Option A: record route (recommended; uses your featureRoutes)
  var url = base + 'x/vuram/financial-crime-compliance/case-details/' + table + '/' + id;

  // Option B: deep link to a specific page (uncomment if you prefer)
  // var url = base + 'workspace/fin-com?page=customer-offboarding-cases&table=' + table + '&sys_id=' + id;

  template.print(url);
})(current, template);
